export const factors={
 durian:[['F1','Shoot maturity and flushing','Record mature leaves and new shoots. An absence of new shoots does not measure high C:N.','Kematangan dan pertumbuhan pucuk','Catat daun matang dan pucuk baharu. Ketiadaan pucuk baharu bukan ukuran C:N tinggi.'],['F2','Water and plant health','Moderate water treatments outperformed the most severely dry D24 treatment for flowering. Longer drought is not automatically better.','Air dan kesihatan pokok','Rawatan air sederhana mengatasi rawatan D24 paling kering bagi pembungaan. Kemarau lebih lama tidak semestinya lebih baik.'],['F1','Variety and local season','D24, Montong and Musang King cannot be treated as interchangeable study subjects. Check local flowering history.','Varieti dan musim tempatan','D24, Montong dan Musang King tidak boleh disamakan sebagai subjek kajian. Semak sejarah bunga tempatan.'],['F2','From induction to fruit set','Induction, bud development and fruit set are separate stages. Visible buds do not justify continuing to pursue higher C:N.','Daripada aruhan kepada buah','Aruhan, perkembangan kudup dan pembentukan buah ialah peringkat berbeza. Kudup yang kelihatan tidak membenarkan usaha berterusan mengejar C:N lebih tinggi.']],
 mango:[['F3','Last shoot age and rest','Synchronised Keitt and Tommy Atkins shoots responded differently to treatments at different months after pruning.','Umur pucuk terakhir dan rehat','Pucuk Keitt dan Tommy Atkins yang diseragamkan memberikan respons berbeza kepada rawatan pada bulan berbeza selepas pangkas.'],['F4','Variety, rootstock and tissue','Leaves and reproductive buds have different C:N, and both rootstock and scion affect results.','Varieti, pokok penanti dan tisu','Daun dan tunas pembiakan mempunyai C:N berbeza; pokok penanti serta sion mempengaruhi hasil.'],['F4','Nitrogen and new shoots','Record nutrition and vegetative growth. Do not deliberately induce deficiency to chase a ratio.','Nitrogen dan pucuk baharu','Catat nutrisi dan pertumbuhan vegetatif. Jangan sengaja menyebabkan kekurangan untuk mengejar nisbah.'],['F3','Climate and treatment context','Read variety, season and treatment together. Five to six months does not mean every mango flowers automatically.','Iklim dan konteks rawatan','Baca varieti, musim dan rawatan bersama. Lima hingga enam bulan tidak bermaksud semua mangga berbunga secara automatik.']],
 citrus:[['F5','Variety and climate','Distinguish lime, sweet orange and mandarin, and tropical versus subtropical conditions.','Varieti dan iklim','Bezakan limau, oren manis dan mandarin serta keadaan tropika dan subtropika.'],['F5','Temperature and water history','Trial responses depend on conditions and duration. One cool night or a count of rainless days is not equivalent.','Sejarah suhu dan air','Respons percubaan bergantung pada keadaan dan tempoh. Satu malam sejuk atau bilangan hari tanpa hujan bukan keadaan setara.'],['F5','Reproductive maturity','Distinguish juvenile seedlings from established bearing trees and record previous fruiting.','Kematangan pembiakan','Bezakan anak biji juvenil daripada pokok matang berbuah dan catat pembuahan terdahulu.'],['F5','Stage of observation','Induction, bud development, pollination and fruit set should be recorded separately.','Peringkat pemerhatian','Aruhan, perkembangan kudup, pendebungaan dan pembentukan buah perlu dicatat berasingan.']],
 longan:[['F6','Variety and flowering context','Long, TDB, XCV and E-Daw have different induction backgrounds. Identify the variety first.','Varieti dan konteks pembungaan','Long, TDB, XCV dan E-Daw mempunyai latar aruhan berbeza. Kenal pasti varieti dahulu.'],['F6','Leaf and shoot age','Leaf-age values occur alongside chemical or girdling treatments, not as independent switches.','Umur daun dan pucuk','Nilai umur daun berkaitan rawatan kimia atau penggelangan, bukan suis bebas.'],['F7','Temperature sequence','Longer cool and warm programmes produced different results. One temperature reading is insufficient.','Urutan suhu','Program sejuk dan panas berpanjangan menghasilkan respons berbeza. Satu bacaan suhu tidak mencukupi.'],['F7','Water and leaf condition','Record temperature, maturity and water; raising C:N cannot replace these observations.','Air dan keadaan daun','Catat suhu, kematangan dan air; meningkatkan C:N tidak menggantikan pemerhatian ini.']],
 pineapple:[['F8','Plant size and age','Whole-plant fresh mass is not fruit mass or a pot weighed with soil.','Saiz dan umur pokok','Jisim segar seluruh pokok bukan jisim buah atau pasu bersama tanah.'],['F8','Variety and production system','Hawaii Smooth Cayenne guidance needs local checking before use with MD2 or other varieties.','Varieti dan sistem pengeluaran','Panduan Smooth Cayenne Hawaii perlu disemak sebelum digunakan untuk MD2 atau varieti lain.'],['F8','Shorter, cooler days','Natural flowering relates to season; hot conditions can reduce induction response.','Siang lebih pendek dan sejuk','Pembungaan semula jadi berkaitan musim; keadaan panas boleh mengurangkan respons aruhan.'],['F8','Induction and nutrition','Separate natural and artificial flowering and record nitrogen management. Do not calculate C:N from biomass.','Aruhan dan nutrisi','Bezakan pembungaan semula jadi dan buatan serta catat pengurusan nitrogen. Jangan kira C:N daripada biojisim.']],
 lychee:[['P2','Variety and climate','Check stable local flowering records; warm lowland and cooler production areas differ.','Varieti dan iklim','Semak rekod pembungaan tempatan; tanah rendah panas berbeza daripada kawasan pengeluaran lebih sejuk.'],['P2','Last flush and nitrogen','Record continued flushing and recent fertilizer. Leaf colour is not a C:N test.','Pucuk terakhir dan nitrogen','Catat pucuk berterusan dan baja terkini. Warna daun bukan ujian C:N.'],['P2','Propagation and age','Seedlings, layered trees and grafted trees may begin bearing at different ages.','Pembiakan dan umur','Anak biji, pokok tut dan pokok cantuman mungkin mula berbuah pada umur berbeza.']],
 avocado:[['P3','Temperature and variety','Bud formation responds to temperature, not only leaf colour or fertilizer.','Suhu dan varieti','Pembentukan kudup dipengaruhi suhu, bukan warna daun atau baja sahaja.'],['P3','Flower types and pollination','A/B flower types and opening times concern pollination, not a C:N induction threshold.','Jenis bunga dan pendebungaan','Jenis bunga A/B dan masa membuka berkaitan pendebungaan, bukan ambang C:N aruhan.']],
 apple:[['P4','Pruning and light','Check heavy pruning and vigorous growth rather than adding stress to replace diagnosis.','Pemangkasan dan cahaya','Semak pemangkasan berat dan pertumbuhan kuat, bukan menambah tekanan sebagai ganti diagnosis.'],['P5','Age, crop load and variety','Record last season’s crop, tree age and rootstock, then check local suitability.','Umur, beban buah dan varieti','Catat hasil musim lalu, umur dan pokok penanti, kemudian semak kesesuaian tempatan.']],
 grape:[['P6','Fruiting wood and buds','Identify last season’s wood and current shoots before attributing missing fruit to C:N.','Kayu berbuah dan mata tunas','Kenal pasti kayu musim lalu dan pucuk semasa sebelum mengaitkan ketiadaan buah dengan C:N.'],['P6','Pruning system','Variety and training determine suitable retained wood and buds; there is no universal heavy-pruning recipe.','Sistem pemangkasan','Varieti dan pembentukan menentukan kayu serta mata tunas yang dikekalkan; tiada resipi pemangkasan berat sejagat.']],
 olive:[['P7','Variety chilling','Winter requirements differ by variety; do not assign one chilling-hour number.','Keperluan sejuk varieti','Keperluan musim sejuk berbeza mengikut varieti; jangan tetapkan satu jumlah jam sejuk.'],['P7','Bud development and water','Shortage of water can impair flower development; drier is not always better.','Perkembangan kudup dan air','Kekurangan air boleh menjejaskan perkembangan bunga; lebih kering tidak sentiasa lebih baik.'],['P7','Pollination','Once flowers exist, check polliniser varieties and flowering weather.','Pendebungaan','Apabila bunga ada, semak varieti pendebunga dan cuaca pembungaan.']],
 strawberry:[['P8','Fruiting type','Identify seasonal, ever-bearing or day-neutral types before interpreting flowering.','Jenis pembuahan','Kenal pasti jenis bermusim, ever-bearing atau day-neutral sebelum mentafsir pembungaan.'],['P8','Light and establishment','Record planting, light, flowers and runners; do not copy temperate calendar months.','Cahaya dan pembentukan awal','Catat penanaman, cahaya, bunga dan sulur; jangan salin bulan kalendar iklim sederhana.']],
 dragonfruit:[['P9','Stems and light','Record stems, support and shade; the source does not validate one lighting duration.','Batang dan cahaya','Catat batang, sokongan dan teduhan; sumber tidak mengesahkan satu tempoh pencahayaan.'],['P9','Night flowers and pollination','Some varieties are self-incompatible; distinguish absent flowers from flowers without fruit.','Bunga malam dan pendebungaan','Sesetengah varieti tidak serasi sendiri; bezakan tiada bunga daripada bunga tanpa buah.']],
 tomato:[['P10','No flowers or no fruit set?','Record flower clusters, opening, drop and fruit set separately.','Tiada bunga atau tiada buah?','Catat jambak, bunga membuka, gugur dan pembentukan buah secara berasingan.'],['P10','Temperature and vegetative growth','Record day/night temperatures, nitrogen and water instead of diagnosing flower drop from C:N alone.','Suhu dan pertumbuhan vegetatif','Catat suhu siang/malam, nitrogen dan air, bukan mendiagnosis bunga gugur daripada C:N sahaja.']],
 pepper:[['P11','Establishment and flowering stage','Seedlings, established plants and fruiting plants have different management goals.','Pembentukan awal dan peringkat bunga','Anak benih, tanaman kukuh dan tanaman berbuah mempunyai matlamat pengurusan berbeza.'],['P11','Heat and water','Investigate heat-related flower drop and water variation; do not diagnose insufficient C:N from them.','Panas dan air','Siasat bunga gugur semasa panas dan perubahan air; jangan mendiagnosis C:N tidak mencukupi daripadanya.']]
};
